import{_ as t,o,c as a,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const i=JSON.parse('{"title":"2005年 · 拓宽护城河","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/2005年.md","filePath":"05_quotes/by-year/2005年.md"}'),r={name:"05_quotes/by-year/2005年.md"};function u(s,e,c,q,h,_){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_2005年-·-拓宽护城河" tabindex="-1">2005年 · 拓宽护城河 <a class="header-anchor" href="#_2005年-·-拓宽护城河" aria-label="Permalink to &quot;2005年 · 拓宽护城河&quot;">​</a></h1><blockquote><p>如果我们让客户满意、消除不必要的成本、改进产品和服务，我们就变得更强大。——巴菲特（75岁）</p></blockquote><p>本页收录2005年致股东信中的经典语录。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>当我们的长期竞争地位因为这些行动而改善时，我们称这种现象为&quot;拓宽护城河&quot;。如果我们要拥有十年或二十年后想要的那种业务，做到这一点是至关重要的。</p></blockquote><blockquote><p>当短期利益与长期利益发生冲突时，拓宽护城河必须优先。</p></blockquote><blockquote><p>保险中的意外绝不是对称的。如果你每遇到十个坏消息才能遇到一个好消息，你已经算幸运了。</p></blockquote><blockquote><p>如果一个问题存在时，无论是人员问题还是业务运营问题，现在就该采取行动。</p></blockquote><blockquote><p>对于投资者整体来说，回报随着运动的增加而减少。</p></blockquote><blockquote><p>一个巨大薪酬从假定数字中流出的业务显然充满危险。</p></blockquote><blockquote><p>很难过度支付一家巨型企业的真正非凡CEO。但这种人很少见。</p></blockquote><blockquote><p>很久以前，马克·吐温说：&quot;试图揪着猫尾巴把猫拖回家的人，会学到一种无法以其他方式学到的教训。&quot;如果吐温现在还在，他可能会尝试经营一家衍生品业务。几天后，他会选择用猫。</p></blockquote><blockquote><p>我们就像一个持续超支的家庭。随着时间的推移，这个家庭发现它为&quot;金融公司&quot;工作得越来越多，为自己工作得越来越少。</p></blockquote><blockquote><p>像一个充满希望的十几岁女孩一样，我会在电话旁等待。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>2005年伯克希尔每股账面价值增长6.4%。卡特里娜飓风造成25亿美元保险损失，但GEICO生产率提升32%的卓越表现弥补了灾难损失。巴菲特完成五项收购，首次提出&quot;拓宽护城河&quot;概念作为长期经营核心原则。他继续退出通用再保险衍生品业务，累计损失达4.04亿美元，并深刻反思自己犹豫不决的代价。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-2005年-翻译-·-01-letters-2005年-核心总结-·-01-letters-2005年-思维导图" tabindex="-1"><a href="/01_letters/2005年/翻译.html">01_letters/2005年/翻译</a> · <a href="/01_letters/2005年/核心总结.html">01_letters/2005年/核心总结</a> · <a href="/01_letters/2005年/思维导图.html">01_letters/2005年/思维导图</a> <a class="header-anchor" href="#_01-letters-2005年-翻译-·-01-letters-2005年-核心总结-·-01-letters-2005年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/2005年/翻译]] · [[→ 核心总结|01_letters/2005年/核心总结]] · [[→ 思维导图|01_letters/2005年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/2005年/翻译.html">/01_letters/2005年/翻译</a></li></ul>',23)])])}const p=t(r,[["render",u]]);export{i as __pageData,p as default};
